        x"FFE1", x"FFF7", x"0007", x"FFFF", x"FFED", x"0000", x"0032", x"004F",
        x"0043", x"0043", x"0071", x"0097", x"0082", x"0055", x"0041", x"0031",
        x"0010", x"FFFC", x"0004", x"000F", x"0008", x"000A", x"0024", x"002E",
        x"0012", x"FFFF", x"001A", x"003B", x"0035", x"001B", x"0012", x"0020",
        x"0032", x"0025", x"FFF3", x"FFD7", x"FFD8", x"FFB7", x"FF8C", x"FFB0"
    );
begin
    process(clk)
    begin
        if rising_edge(clk) then
            if en = '1' then
                sample_out <= rom(to_integer(addr));
            end if;
        end if;
    end process;
end architecture;
